    // Check if all items in the checklist are marked as done
    boolean allItemsDone = checklist?.all { item -> item.done } ? : false

    // If any item is not done, return an error message and prevent the transition
    if (!allItemsDone) {
        trans.error("All items in the checklist must be marked as done before moving to the next column.")
        return true
    }

    // If all items are done, allow the transition
    return false
}

