#include <iostream>
#include <iomanip> // Required for setprecision()

int main() {
   const double PURCHASE_PRICE = 1000;
   const double RESIDUAL_VALUE = 200;
   const double REFUND = 600;

   double originalPricePaid = PURCHASE_PRICE - RESIDUAL_VALUE;
   double percentageOfRefund = static_cast<double>(REFUND) / originalPricePaid;
   int wholeNumberPercentage = std::round(percentageOfRefund * 100);

   std::cout << "The percentage of refund is: ";
   std::cout << std::fixed << std::setprecision(2) << percentageOfRefund * 100 << "%";
   std::cout << " (equivalent to " << wholeNumberPercentage << " whole numbers)\n";

   return 0;
}
```

