Here's a Swift function that identifies and replaces common homophone mistakes:

```swift
func replaceHomophones(_ text: String) -> String {
    let homophones = [
        ("there", "they're", "their"), // Commonly confused words
        ("your", "you're"),
        ("we", "wi'"), // Less commonly confused words
        ("two", "too") // Even less commonly confused words
    ]

    var result = ""
    for (_, words) in homophones.enumerated() {
        let startIndex = text.firstIndex(of: words[0], options: .caseInsensitive) ?? 0

        while let index = text.index(text.startIndex, offset: startIndex) {
            let substring = String(text[index..<min(index+words[1].count, text.endIndex)])

            guard Set(substring.lowercased().unicodeScalars).subsets(where: \.count == words[1].count).first?.elementsEqual(Set(words[1].lowercased().unicodeScalars)) else {
                continue // Not a match, move on to the next occurrence
            }

            let replacementIndex = index + words[1].count
            let endIndex = min(text.index(text.startIndex, offset: replacementIndex), text.endIndex)
            let replacedSubstring = String(text[..<replacementIndex] + String(replacements: words[2], for: words[1], in: text[replacementIndex...endIndex]))

            result += String(text[..<index]) + replacedSubstring + String(text[endIndex...])
            text = String(text[..<index] + text[max(replacementIndex, index+words[1].count)...]) // Move the remaining text over to avoid duplicating matches
        }
    }
    return result
}
```

