function getNestedValues(object, path) {
  const keys = path.split(".");
  let result = object;

  for (let I = 0; I < keys.length - 1; i++) {
    if (!result[keys[i]]) {
      return []; // If any intermediate key is missing, return an empty array
    }
    result = result[keys[i]];
  }

  const lastKey = keys[keys.length - 1];
  const values = [];

  // Add all values with the given last key to the result array
  Object.values(result).forEach(value => {
    values.push(value[lastKey]);
  });

  return values;
}

